INSERT INTO properties (id, title, price, price_display, price_usd, price_display_usd, type, location, provincia_id, canton_id, distrito_id, beds, baths, area, parking, property_type, status, description, images, instagram, video, lat, lng, contact_number) VALUES
('1', 'Residencia Moderna en Escazú', 620000000, '₡620,000,000', 1215686, '$1,215,686', 'sale', 'Escazú, San José', '1', '2', '1', 4, 3, '350 m²', 2, 'Casa', 'available', 'Espectacular residencia de líneas modernas ubicada en una de las zonas más exclusivas de Escazú. Cuenta con amplios espacios, acabados de primera calidad, cocina equipada, terraza con vista al valle central y jardín privado. Perfecta para familias que buscan comodidad y elegancia.', '["https://homepropertiescostarica.com/wp-content/uploads/2021/04/bonavista-cocina-comedor-sala-A-min-960x600.jpg","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example1/', 'https://www.instagram.com/reel/example1/', 9.9280, -84.1385, '50670141868'),

('2', 'Apartamento de Lujo Minimalista', 2300000, '₡2,300,000/mes', 4500, '$4,500/mes', 'rent', 'Santa Ana, San José', '1', '9', '1', 2, 2, '120 m²', 1, 'Apartamento', 'available', 'Elegante apartamento con diseño minimalista en el corazón de Santa Ana. Espacios abiertos con iluminación natural, acabados modernos, cocina integral y acceso a amenidades del condominio incluyendo piscina, gimnasio y áreas sociales.', '["https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1484154218962-a197022b5858?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example2/', 'https://www.instagram.com/reel/example2/', 9.9362, -84.1827, '50670141868'),

('3', 'Villa con Vista al Mar', 1450000000, '₡1,450,000,000', 2843137, '$2,843,137', 'sale', 'Tamarindo, Guanacaste', '5', '3', '9', 5, 4, '480 m²', 3, 'Casa', 'presale', 'Impresionante villa frente al océano Pacífico en Tamarindo. Diseño tropical contemporáneo con piscina infinity, terraza panorámica, suite principal con vista al mar y acceso directo a la playa. Una joya para quienes buscan el paraíso.', '["https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600596542815-3ad309796793?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600585154340-be6199f7c009?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1573052905904-34ad8c27f0cc?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example3/', 'https://www.instagram.com/reel/example3/', 10.2994, -85.8375, '50670141868'),

('4', 'Penthouse Exclusivo en Sabana', 1810000000, '₡1,810,000,000', 3549020, '$3,549,020', 'sale', 'La Sabana, San José', '1', '1', '8', 3, 3.5, '280 m²', 2, 'Apartamento', 'available', NULL, '["https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example4/', 'https://www.instagram.com/reel/example4/', 9.9361, -84.1044, '50670141868'),

('5', 'Casa de Campo en Atenas', 7750000, '₡7,750,000/mes', 15196, '$15,196/mes', 'rent', 'Atenas, Alajuela', '2', '5', '1', 4, 4, '400 m²', 2, 'Casa', 'available', 'Hermosa casa de campo rodeada de naturaleza en Atenas, conocida por tener el mejor clima del mundo. Amplios jardines, piscina, rancho con BBQ, vistas espectaculares al valle y total privacidad. Ideal para desconectarse sin alejarse de la ciudad.', '["https://images.unsplash.com/photo-1518780664697-55e3ad937233?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example5/', 'https://www.instagram.com/reel/example5/', 9.9757, -84.3827, '50670141868'),

('6', 'Loft Moderno en Barrio Escalante', 14500000, '₡14,500,000/mes', 28431, '$28,431/mes', 'rent', 'San José Centro', '1', '1', '1', 1, 1.5, '85 m²', 1, 'Apartamento', 'available', 'Loft de diseño contemporáneo en el vibrante Barrio Escalante. Techos altos, espacios abiertos tipo industrial, cocina gourmet y ubicación inmejorable rodeada de los mejores restaurantes y cafés de San José.', '["https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1484154218962-a197022b5858?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example6/', 'https://www.instagram.com/reel/example6/', 9.9381, -84.0690, '50670141868'),

('7', 'Mansión en Lindora', 2845000000, '₡2,845,000,000', 5578431, '$5,578,431', 'sale', 'Santa Ana, San José', '1', '9', '3', 6, 7, '650 m²', 4, 'Casa', 'investment', 'Majestuosa mansión en el exclusivo sector de Lindora. Arquitectura de autor, materiales importados, home theater, bodega de vinos, piscina climatizada, jardines manicurados y seguridad 24/7. El máximo nivel de vida en Costa Rica.', '["https://escazu-properties.com/cache/7b1cfd3f91cd961601b28e09051ed609_w1280.jpg","https://images.unsplash.com/photo-1600585154340-be6199f7c009?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600607687939-ce8a-6c25118c?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/scrpropiedades', 'https://www.instagram.com/reel/DKc50ypplGz/', 9.9513, -84.1952, '50670141868'),

('8', 'Departamento Familiar en Heredia', 930000000, '₡930,000,000', 1823529, '$1,823,529', 'sale', 'Heredia', '4', '1', '1', 3, 2, '160 m²', 2, 'Apartamento', 'presale', 'Amplio departamento familiar en una zona tranquila de Heredia. Cerca de universidades, centros comerciales y con fácil acceso a San José. Áreas comunes con juegos infantiles, salón de eventos y seguridad.', '["https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1484154218962-a197022b5858?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example8/', 'https://www.instagram.com/reel/example8/', 10.0024, -84.1165, '50670141868'),

('9', 'Lote Residencial en Guanacaste', 440000000, '₡440,000,000', 862745, '$862,745', 'sale', 'Flamingo, Guanacaste', '5', '3', '8', 0, 0, '1,200 m²', 0, 'Lote', 'available', 'Exclusivo lote residencial en Playa Flamingo con vista al mar. Terreno plano listo para construir, acceso a servicios públicos, en comunidad cerrada con seguridad. A minutos de la playa y del aeropuerto de Liberia.', '["https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1573052905904-34ad8c27f0cc?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1600596542815-3ad309796793?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example9/', 'https://www.instagram.com/reel/example9/', 10.4395, -85.7827, '50670141868'),

('10', 'Oficina en Centro Corporativo', 750000, '₡750,000/mes', 1470, '$1,470/mes', 'rent', 'Escazú, San José', '1', '2', '1', 0, 1, '65 m²', 2, 'Comercial', 'available', 'Moderna oficina ubicada en prestigioso centro corporativo en Escazú. Cuenta con acabados de lujo, aire acondicionado central, seguridad 24/7, parqueo para visitas y excelente ubicación cerca de bancos y comercios.', '["https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example10/', 'https://www.instagram.com/reel/example10/', 9.9320, -84.1450, '50670141868'),

('11', 'Finca Ganadera en San Carlos', 320000000, '₡320,000,000', 627450, '$627,450', 'sale', 'San Carlos, Alajuela', '2', '10', '1', 0, 0, '50,000 m²', 0, 'Finca', 'available', 'Hermosa finca de 5 hectáreas con topografía plana y ondulada suave. Cuenta con nacientes de agua, empastada, cercas en buen estado y acceso por calle pública. Ideal para proyecto ganadero o desarrollo turístico.', '["https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80"]', 'https://www.instagram.com/reel/example11/', 'https://www.instagram.com/reel/example11/', 10.3238, -84.4351, '50670141868');
